Here's a complete example of data-driven MSTest tests for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // --- DataRow: inline test cases ---

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    [DataRow(100, 0.01, 1.00)]
    public void CalculateTotal_ReturnsExpected(int quantity, double unitPrice, double expected)
    {
        var result = _calculator.CalculateTotal(quantity, (decimal)unitPrice);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(100.00, 0.10, 90.00)]   // 10% off
    [DataRow(100.00, 0.00, 100.00)]  // no discount
    [DataRow(50.00, 0.50, 25.00)]    // 50% off
    [DataRow(200.00, 1.00, 0.00)]    // 100% off
    public void ApplyDiscount_ReturnsExpected(double price, double discount, double expected)
    {
        var result = _calculator.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData: complex/reusable test cases ---

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases), DynamicDataSourceType.Method)]
    public void CalculateTotal_DynamicCases(int quantity, decimal unitPrice, decimal expected)
    {
        var result = _calculator.CalculateTotal(quantity, unitPrice);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    [DynamicData(nameof(ApplyDiscountEdgeCases), DynamicDataSourceType.Property)]
    public void ApplyDiscount_EdgeCases(decimal price, decimal discount, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discount);
        Assert.AreEqual(expected, result);
    }

    // DynamicData sources

    private static IEnumerable<object[]> CalculateTotalCases()
    {
        yield return new object[] { 1, 0.01m, 0.01m };
        yield return new object[] { 999, 9.99m, 9980.01m };
        yield return new object[] { 2, 19.95m, 39.90m };
    }

    public static IEnumerable<object[]> ApplyDiscountEdgeCases =>
        new List<object[]>
        {
            new object[] { 0.01m, 0.10m, 0.009m },
            new object[] { 999999.99m, 0.25m, 749999.9925m },
            new object[] { 0m, 0.50m, 0m },
        };
}
```

**Key points:**

- **`[DataRow]`** — best for simple inline cases; limited to compile-time constants (no `decimal` literals, so use `double` and cast).
- **`[DynamicData]`** — use a method or property returning `IEnumerable<object[]>` for complex types like `decimal`, or when cases are generated/shared.
- **`[TestInitialize]`** — sets up a fresh instance per test.
- Each test method is focused on one behavior with descriptive naming (`Method_Scenario`).

Adjust the method signatures to match your actual `PriceCalculator` API.
